CREATE TABLE IF NOT EXISTS canonical_capital_profiles (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), project_id uuid NOT NULL REFERENCES projects(id) ON DELETE CASCADE, capital_required numeric, currency text NOT NULL DEFAULT 'NGN', minimum_capital numeric, maximum_capital numeric, use_of_funds text, revenue_model text, expected_cashflow numeric, tenor_months integer, risk_profile text, security_type text, security_notes text, sponsor_contribution numeric, development_stage text, governance_notes text, capital_readiness_score integer NOT NULL DEFAULT 0, capital_readiness_state text NOT NULL DEFAULT 'not_assessed', evidence_score integer NOT NULL DEFAULT 0, verification_score integer NOT NULL DEFAULT 0, economics_score integer NOT NULL DEFAULT 0, governance_score integer NOT NULL DEFAULT 0, risk_score integer NOT NULL DEFAULT 0, repayment_score integer NOT NULL DEFAULT 0, assessed_at timestamptz, created_by text, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now(), UNIQUE(project_id));